def get_repo_metadata(fields=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0055000" if __import__("os").path.isdir("./environment_mix/0055000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate fields
    if fields is not None:
        if not isinstance(fields, list) or any(not isinstance(s, str) for s in fields):
            return _err("VALIDATION_ERROR", "fields must be an array of strings")

    raw = _load("repo_metadata.json")
    # Datastore might contain [] or {} depending on snapshot; normalize to dict
    metadata = raw if isinstance(raw, dict) else {}
    if not metadata:
        # Read with no matches returns empty object (not error)
        return {"data": {}, "meta": {"fields_applied": bool(fields)}}

    if fields is None:
        return {"data": metadata, "meta": {"fields_applied": False}}

    # Only return keys that exist; omit unknown ones
    projected = {k: metadata[k] for k in fields if k in metadata}
    return {"data": projected, "meta": {"fields_applied": True}}

def list_issues_prs(state=None, user=None, number=None, limit=None, fields=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0055000" if __import__("os").path.isdir("./environment_mix/0055000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if state is not None and state not in ("open", "closed"):
        return _err("VALIDATION_ERROR", "Unsupported state value", allowed=["open", "closed"])
    if number is not None and not isinstance(number, int):
        return _err("VALIDATION_ERROR", "number must be an integer")
    if limit is not None and not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit is not None and limit < 0:
        return _err("VALIDATION_ERROR", "limit must be >= 0")
    if fields is not None:
        if not isinstance(fields, list) or any(not isinstance(s, str) for s in fields):
            return _err("VALIDATION_ERROR", "fields must be an array of strings")

    lim = 20 if limit is None else limit

    rows = _load("issues_prs.json")
    if not isinstance(rows, list):
        rows = []

    # Filtering
    out = []
    for it in rows:
        if not isinstance(it, dict):
            continue
        if state is not None and it.get("state") != state:
            continue
        if user is not None and it.get("user") != user:
            continue
        if number is not None and it.get("number") != number:
            continue
        out.append(it)

    # If number provided but not found -> refuse
    if number is not None and not out:
        return _err("NOT_FOUND", "No issue/PR found for the specified number", number=number)

    # Sort recent first by created_at if present (ISO 8601 Z sorts lexicographically)
    out.sort(key=lambda x: x.get("created_at") or "", reverse=True)

    total = len(out)
    page = out[:lim] if lim is not None else out
    has_more = total > len(page)

    # Field projection
    if fields is not None:
        page = [{k: it[k] for k in fields if k in it} for it in page]

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": lim,
            "has_more": has_more
        }
    }

def list_commits(author=None, since=None, until=None, sha=None, limit=None, fields=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0055000" if __import__("os").path.isdir("./environment_mix/0055000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate limit/fields
    if limit is not None and not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit is not None and limit < 0:
        return _err("VALIDATION_ERROR", "limit must be >= 0")
    if fields is not None:
        if not isinstance(fields, list) or any(not isinstance(s, str) for s in fields):
            return _err("VALIDATION_ERROR", "fields must be an array of strings")

    # Validate since/until ISO date-time
    def _parse_dt(s, label):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(label)
        ss = s.strip()
        # Accept Z suffix
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        # fromisoformat requires timezone in +00:00 form if present
        return datetime.datetime.fromisoformat(ss)

    try:
        since_dt = _parse_dt(since, "since")
        until_dt = _parse_dt(until, "until")
    except ValueError as e:
        bad = str(e) if str(e) in ("since", "until") else "date"
        return _err("VALIDATION_ERROR", f"Invalid date-time value for {bad}")

    lim = 20 if limit is None else limit

    rows = _load("commits.json")
    if not isinstance(rows, list):
        rows = []

    def _commit_dt(it):
        d = it.get("date")
        if not isinstance(d, str) or not d:
            return None
        try:
            ds = d.strip()
            if ds.endswith("Z"):
                ds = ds[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ds)
        except Exception:
            return None

    out = []
    for it in rows:
        if not isinstance(it, dict):
            continue
        if sha is not None and it.get("sha") != sha:
            continue
        if author is not None and it.get("author") != author:
            continue

        cdt = _commit_dt(it)
        if since_dt is not None and cdt is not None and cdt <= since_dt:
            continue
        if until_dt is not None and cdt is not None and cdt >= until_dt:
            continue

        out.append(it)

    # If sha provided but not found -> refuse
    if sha is not None and not out:
        return _err("NOT_FOUND", "No commit found for the specified sha", sha=sha)

    # Sort recent first by date when present
    out.sort(key=lambda x: x.get("date") or "", reverse=True)

    total = len(out)
    page = out[:lim] if lim is not None else out
    has_more = total > len(page)

    if fields is not None:
        page = [{k: it[k] for k in fields if k in it} for it in page]

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": lim,
            "has_more": has_more
        }
    }

def list_root_contents(entry_type=None, path_prefix=None, limit=None, fields=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0055000" if __import__("os").path.isdir("./environment_mix/0055000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if entry_type is not None and entry_type not in ("file", "dir"):
        return _err("VALIDATION_ERROR", "Unsupported entry_type value", allowed=["file", "dir"])
    if limit is not None and not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit is not None and limit < 0:
        return _err("VALIDATION_ERROR", "limit must be >= 0")
    if fields is not None:
        if not isinstance(fields, list) or any(not isinstance(s, str) for s in fields):
            return _err("VALIDATION_ERROR", "fields must be an array of strings")
    if path_prefix is not None and not isinstance(path_prefix, str):
        return _err("VALIDATION_ERROR", "path_prefix must be a string")

    lim = 20 if limit is None else limit

    rows = _load("contents.json")
    if not isinstance(rows, list):
        rows = []

    out = []
    for it in rows:
        if not isinstance(it, dict):
            continue
        if entry_type is not None and it.get("type") != entry_type:
            continue
        p = it.get("path")
        if path_prefix is not None:
            if not isinstance(p, str) or not p.startswith(path_prefix):
                continue
        out.append(it)

    # Deterministic ordering: by path then name
    out.sort(key=lambda x: ((x.get("path") or ""), (x.get("name") or "")))

    total = len(out)
    page = out[:lim] if lim is not None else out
    has_more = total > len(page)

    if fields is not None:
        page = [{k: it[k] for k in fields if k in it} for it in page]

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": lim,
            "has_more": has_more
        }
    }
